{
  "findings": [
    {
      "check_id": "CKV_AZURE_70",
      "title": "Function App does not enforce HTTPS",
      "resource": "azurerm_linux_function_app.alert_function",
      "severity": "HIGH",
      "explanation": "The Function App does not set https_only, whose default permits unencrypted HTTP connections. This can expose requests and application data to interception in transit."
    }
  ],
  "patched_code": "resource "azurerm_linux_function_app" "alert_function" {
  name                = "smart-manufacturing-iot-monitoring-platform-function-app-alerts"
  resource_group_name = azurerm_resource_group.smart_manufacturing.name
  location            = azurerm_resource_group.smart_manufacturing.location
  service_plan_id     = azurerm_service_plan.dashboard_plan.id
  storage_account_name       = azurerm_storage_account.function_storage.name
  storage_account_access_key = azurerm_storage_account.function_storage.primary_access_key
  https_only                 = true
  site_config {
    application_stack {
      node_version = "18"
    }
  }
  app_settings = {
    "FUNCTIONS_WORKER_RUNTIME" = "node"
  }
}
",
  "fix_summary": "Enabled HTTPS-only access for the Function App to prevent unencrypted HTTP traffic."
}
